CREATE TABLE IF NOT EXISTS brand_models (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, display_name TEXT NOT NULL, adult_age_range TEXT NOT NULL, presentation TEXT, archetype TEXT NOT NULL, appearance_description TEXT, styling TEXT, hair TEXT, aesthetic TEXT, wardrobe_direction TEXT, visual_energy TEXT, preferred_environments JSONB NOT NULL DEFAULT '[]', reference_object_paths JSONB NOT NULL DEFAULT '[]', reference_rights_acknowledged_at TIMESTAMPTZ, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS brand_models_business_id_idx ON brand_models(business_id);
CREATE TABLE IF NOT EXISTS mockup_projects (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE RESTRICT, campaign_id TEXT REFERENCES campaigns(id) ON DELETE SET NULL, brand_model_id TEXT REFERENCES brand_models(id) ON DELETE SET NULL, creation_path TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', approved_visual_id TEXT, creative_direction JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS mockup_projects_user_id_idx ON mockup_projects(user_id);
CREATE TABLE IF NOT EXISTS mockup_versions (id TEXT PRIMARY KEY, mockup_project_id TEXT NOT NULL REFERENCES mockup_projects(id) ON DELETE CASCADE, version_number INTEGER NOT NULL, object_path TEXT, status TEXT NOT NULL DEFAULT 'draft', revision_request TEXT, qa_decision TEXT, qa_checks JSONB NOT NULL DEFAULT '{}', provider_job_ref TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(mockup_project_id, version_number));
DO $$ BEGIN ALTER TABLE mockup_projects ADD CONSTRAINT mockup_projects_approved_visual_fk FOREIGN KEY (approved_visual_id) REFERENCES mockup_versions(id) ON DELETE SET NULL; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
